function updateSpin(){if(!player.spin)return;player.spin--;const p=player;for(const e of [...enemies,...critters])if(!e.dead&&(!e.pipeTop||e.exposure>4)&&Math.abs(e.x+(e.w||26)/2-(p.x+p.w/2))<p.w/2+32&&Math.abs(e.y+(e.h||24)/2-(p.y+p.h/2))<p.h/2+20)defeat(e);if(p.spin===15){const tx=Math.floor((p.x+(p.face>0?p.w+8:-8))/T),ty=Math.floor((p.y+p.h*.6)/T);if(tx>=0&&tx<W&&ty>=0&&ty<H)hitBlock(tx,ty,{x:tx*T,y:ty*T})}}
