function swordBox(p){return {x:p.face>0?p.x+p.w-4:p.x-34,y:p.y-8,w:38,h:p.h+10}}
function updateSword(){const p=player;if(!p.swing)return;p.swing--;const b=swordBox(p);for(const e of [...enemies,...critters])if(!e.dead&&(!e.pipeTop||e.exposure>4)&&overlap(b,{x:e.x,y:e.y,w:e.w||26,h:e.h||24}))defeat(e);for(const h of hazards)if(!h.dead&&overlap(b,h)){h.dead=true;debris.push({x:h.x,y:h.y,vx:p.face*2,vy:-3,life:16,rock:true})}if(p.swing===10){const tx=Math.floor((p.x+(p.face>0?p.w+10:-10))/T),ty=Math.floor((p.y+p.h*.5)/T);if(tx>=0&&tx<W&&ty>=0&&ty<H)hitBlock(tx,ty,{x:tx*T,y:ty*T})}}
