 p.vx=((keys.ArrowRight||keys.KeyD)?speed:0)-((keys.ArrowLeft||keys.KeyA)?speed:0);if(p.vx)p.face=Math.sign(p.vx);p.anim=p.vx?p.anim+Math.abs(p.vx):0;
